def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    lm = my[-1]
    lo = op[-1]

    opp_D = 0
    for x in op:
        if x == 'D':
            opp_D += 1
    opp_C = n - opp_D

    # If the opponent has never defected, start a short probe and keep
    # defecting while they remain cooperative. This strongly exploits
    # unconditional and very forgiving opponents.
    if opp_D == 0:
        if n >= 5:
            return 'D'
        return 'C'

    # Count defections that look unprovoked: opponent D after our C.
    unprov = 0
    recent_unprov = 0
    start_recent = n - 10
    if start_recent < 0:
        start_recent = 0
    for i in range(n):
        if op[i] == 'D':
            if i == 0 or my[i - 1] == 'C':
                unprov += 1
                if i >= start_recent:
                    recent_unprov += 1

    # Learn how opponent responds to our previous action.
    c_tot = 0
    d_tot = 0
    c_to_c = 0
    d_to_c = 0
    for i in range(n - 1):
        if my[i] == 'C':
            c_tot += 1
            if op[i + 1] == 'C':
                c_to_c += 1
        else:
            d_tot += 1
            if op[i + 1] == 'C':
                d_to_c += 1

    pC = c_to_c / c_tot if c_tot else 1.0
    pD = d_to_c / d_tot if d_tot else 0.0

    last10D = 0
    for x in op[-10:]:
        if x == 'D':
            last10D += 1

    dstreak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            dstreak += 1
        else:
            break

    # If the opponent is essentially a hard defector, best-respond with D.
    if opp_C == 0 or (opp_D >= 6 and opp_D * 5 >= n * 4 and last10D >= 8):
        return 'D'

    # No data on how they respond to our D yet: use simple retaliation.
    if d_tot == 0:
        if lo == 'D':
            return 'D'
        if opp_D >= 2 and opp_D * 2 >= n:
            return 'D'
        return 'C'

    # Strongly retaliatory: they reward C and punish D.
    retaliatory = (pC >= 0.65 and pD <= 0.35 and (pC - pD) >= 0.30)

    if retaliatory:
        if lo == 'D':
            if lm == 'D':
                # Break revenge spirals, unless they have become a hard defector.
                if dstreak >= 5 or last10D >= 8:
                    return 'D'
                if last10D >= 7 and opp_C * 3 <= n:
                    return 'D'
                return 'C'

            # We cooperated and they defected.
            if dstreak >= 5 or last10D >= 8:
                return 'D'

            provoked = (n >= 2 and my[-2] == 'D')
            if provoked or (dstreak <= 3 and unprov <= 2):
                return 'C'

            # Short bursts from an otherwise cooperative retaliator.
            if dstreak <= 4 and opp_C * 10 >= n * 4 and unprov <= 4:
                return 'C'

            if recent_unprov >= 2 or unprov >= 4:
                return 'D'

            # Rare mistakes: forgive often enough to restore cooperation.
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        else:
            # They cooperated. Keep mutual cooperation, with a tiny late probe
            # only if they have never defected after our cooperation.
            if lm == 'D':
                return 'C'
            if n >= 92 and unprov == 0 and rng.random() < 0.01:
                return 'D'
            return 'C'

    # Not clearly retaliatory: opponent is tolerant, independent, or exploitative.
    # Prefer defection when it is likely to be profitable.
    if lo == 'D':
        if lm == 'D':
            # Mutual D: reset unless they look hard or uncooperative.
            if dstreak >= 5 or last10D >= 7 or unprov >= max(4, n // 4):
                return 'D'
            return 'C'

        # CD: they defected after our cooperation.
        if (dstreak >= 5 or last10D >= 7 or pC <= 0.45 or
                recent_unprov >= 2 or unprov >= max(4, n // 4)):
            return 'D'

        # A short burst against a mostly cooperative opponent is often noise-like
        # (e.g. a timed defection followed by return to C), so forgive it.
        if dstreak <= 4 and opp_C * 10 >= n * 5 and unprov < max(3, n // 5):
            return 'C'

        if rng.random() < 0.55:
            return 'D'
        return 'C'

    else:
        if lm == 'D':
            # We defected and they cooperated. If they tolerate D, keep exploiting.
            if pD >= 0.55 or opp_D <= 2 or pC <= 0.45:
                return 'D'
            return 'C'

        # CC: exploit if they remain cooperative even after our D, or if they are
        # generally uncooperative so D is the safer best response.
        if pC <= 0.45:
            return 'D'

        if d_tot >= 2 and pD >= 0.55 and pC >= 0.35:
            if rng.random() < 0.80:
                return 'D'
            return 'C'

        if d_tot < 2 and opp_D <= 2 and n >= 5:
            # A small learning probe against a possibly tolerant opponent.
            if rng.random() < 0.12:
                return 'D'

        return 'C'
